#!/usr/bin/env python3
"""Inspect workspace: list files and confirm target PDF exists."""
import os
import sys

cwd = os.getcwd()
print("CWD:", cwd)
entries = sorted(os.listdir(cwd))
print("Entries:", entries)

pdfs = [e for e in entries if e.lower().endswith(".pdf")]
print("PDFs found:", pdfs)

target = "report.pdf"
if target in entries:
    print("Target exists:", target, "size:", os.path.getsize(target))
else:
    print("Target NOT found in CWD")
    # Look one level up and a few common locations
    for base in [os.path.dirname(cwd), os.path.join(cwd, "files"), os.path.join(cwd, "data")]:
        if os.path.isdir(base):
            for e in sorted(os.listdir(base)):
                if e.lower().endswith(".pdf"):
                    print("PDF elsewhere:", os.path.join(base, e))

#!/usr/bin/env python3
"""Task-local validator for the report.pdf cover page added by add_report_cover.py.

Opens only report.pdf and checks that page 1 is a cover page carrying the exact
title "Annual Financial Report" and the operator runtime current date, and that
the document retains original content after the added cover.
"""

import datetime
import os
import sys

from pypdf import PdfReader

INPUT_PDF = "report.pdf"
TITLE = "Annual Financial Report"


def today_label():
    today = datetime.date.today()
    return "{} {}, {}".format(today.strftime("%B"), today.day, today.year)


def main():
    if not os.path.isfile(INPUT_PDF):
        print("error: {} missing".format(INPUT_PDF), file=sys.stderr)
        return 1

    reader = PdfReader(INPUT_PDF)
    page_count = len(reader.pages)
    if page_count < 1:
        print("FAIL: report.pdf has no pages")
        return 1

    page1_text = " ".join((reader.pages[0].extract_text() or "").split())
    failures = []
    for name, needle in (("exact title", TITLE), ("current date", today_label())):
        if needle not in page1_text:
            failures.append("page 1 is missing the {} ({!r})".format(name, needle))
        else:
            print("PASS: page 1 contains the {} ({!r})".format(name, needle))

    if page_count < 2:
        failures.append("expected the cover page followed by original content")
    else:
        print("PASS: report.pdf has {} pages (cover + original content)".format(page_count))

    print("first-page text preview: {}".format(page1_text[:160]))
    if failures:
        for f in failures:
            print("FAIL: " + f)
        return 1
    print("VALIDATION PASSED")
    return 0


if __name__ == "__main__":
    sys.exit(main())
